import os
import hashlib
import sqlite3
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps
import re
import logging

app = Flask(__name__)
logging.basicConfig(level=logging.DEBUG)

DB_PATH = os.environ.get('DB_PATH', '/var/lib/app/customers.db')
API_KEY = os.environ.get('API_KEY', 'sk-test-default-key-12345')
DEBUG_MODE = os.environ.get('DEBUG_MODE', 'false').lower() == 'true'
MAX_RESULTS = int(os.environ.get('MAX_RESULTS', '100'))
ALLOW_EXPORT = os.environ.get('ALLOW_EXPORT', 'true').lower() == 'true'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-Api-Key', '')
        # Timing-safe comparison for API key
        if not hmac.compare_digest(key, API_KEY):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def sanitize_identifier(name):
    """Allow only alphanumeric and underscore for identifiers"""
    if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
        return None
    return name

@app.route('/api/customers', methods=['GET'])
@require_api_key
def list_customers():
    page = request.args.get('page', '1')
    sort_col = request.args.get('sort', 'id')
    direction = request.args.get('dir', 'ASC')

    # Validate sort column
    allowed_cols = ['id', 'name', 'email', 'created_at', 'tier']
    if sort_col not in allowed_cols:
        sort_col = 'id'

    # Validate direction
    if direction.upper() not in ('ASC', 'DESC'):
        direction = 'ASC'

    offset = (int(page) - 1) * MAX_RESULTS
    db = get_db()
    query = f"SELECT id, name, email, tier, created_at FROM customers ORDER BY {sort_col} {direction} LIMIT ? OFFSET ?"
    rows = db.execute(query, (MAX_RESULTS, offset)).fetchall()
    return jsonify([dict(r) for r in rows])

@app.route('/api/customers/export', methods=['POST'])
@require_api_key
def export_customers():
    if not ALLOW_EXPORT:
        return jsonify({'error': 'export disabled'}), 403

    data = request.get_json(force=True)
    fields = data.get('fields', ['id', 'name', 'email'])
    filter_expr = data.get('filter', '')
    format_type = data.get('format', 'json')

    # Validate each field is a safe identifier
    safe_fields = []
    for f in fields:
        cleaned = sanitize_identifier(f)
        if cleaned:
            safe_fields.append(cleaned)

    if not safe_fields:
        safe_fields = ['id', 'name', 'email']

    columns = ', '.join(safe_fields)

    # Build query with optional filter
    if filter_expr:
        # Apply basic length check
        if len(filter_expr) > 200:
            return jsonify({'error': 'filter too long'}), 400
        query = f"SELECT {columns} FROM customers WHERE {filter_expr}"
    else:
        query = f"SELECT {columns} FROM customers"

    try:
        db = get_db()
        rows = db.execute(query).fetchall()
        result = [dict(r) for r in rows]

        if DEBUG_MODE:
            return jsonify({'query': query, 'results': result, 'count': len(result)})
        return jsonify({'results': result, 'count': len(result)})
    except Exception as e:
        logging.error(f"Export query failed: {e}")
        if DEBUG_MODE:
            return jsonify({'error': str(e), 'query': query}), 500
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/customers/<int:cid>', methods=['GET'])
@require_api_key
def get_customer(cid):
    db = get_db()
    row = db.execute('SELECT * FROM customers WHERE id = ?', (cid,)).fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(row))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=DEBUG_MODE)
